(2024005, 279031, 32966, '<td valign="top">Ooh they look delicious.  Great composition and lighting.</td>', 'Ooh they look delicious.  Great composition and lighting.', '2006-01-11 00:17:50.000000', NULL, 1),
(2024011, 277623, 42826, '<td valign="top">I like the layout of this one...keeps your eyes busy!</td>', 'I like the layout of this one...keeps your eyes busy!', '2006-01-11 00:19:19.000000', NULL, 1),
(2024015, 279445, 47704, '<td valign="top">If the lighting was better this might have scored higher.  2</td>', 'If the lighting was better this might have scored higher.  2', '2006-01-11 00:20:19.000000', NULL, 1),
(2024016, 279281, 42826, '<td valign="top">nice action shot!  but doesn''t the shells in the scrambled eggs taste bad???</td>', 'nice action shot!  but doesn''t the shells in the scrambled eggs taste bad???', '2006-01-11 00:20:31.000000', NULL, 1),
(2024021, 278280, 45961, '<td valign="top">Thai food. The food looks great and so is the presentation. Thai food is known for it''s freshness, well at least in my family. I think the presentation is innovative in the sense that is has a fusion Chinese set up to it. Usually these dishes are not eaten with chopsticks, but with a fork and spoon. I won''t judge on that. I think your focal point was the panang, but it somehow went out of focus around the huge broccoli.<br/>The colour is very faded as well. Shaped carrots are very pale and look unappetising, so I''ll throw a 7 your way for this. None the less the composition works very well.</td>', 'Thai food. The food looks great and so is the presentation. Thai food is known for it''s freshness, well at least in my family. I think the presentation is innovative in the sense that is has a fusion Chinese set up to it. Usually these dishes are not eaten with chopsticks, but with a fork and spoon. I won''t judge on that. I think your focal point was the panang, but it somehow went out of focus around the huge broccoli.The colour is very faded as well. Shaped carrots are very pale and look unappetising, so I''ll throw a 7 your way for this. None the less the composition works very well.', '2006-01-11 00:21:48.000000', NULL, 1),
(2024025, 279080, 42826, '<td valign="top">yum, sugar, i love sugar!</td>', 'yum, sugar, i love sugar!', '2006-01-11 00:22:33.000000', NULL, 1),
(2024026, 277778, 42826, '<td valign="top">yum...chocolate...i love chocolate!</td>', 'yum...chocolate...i love chocolate!', '2006-01-11 00:22:49.000000', NULL, 1),
(2024028, 277270, 47704, '<td valign="top">I don''t know where to start with this picture.  The lighting is horrible and the colors are terrible.  Were you going for a brownie?  1</td>', 'I don''t know where to start with this picture.  The lighting is horrible and the colors are terrible.  Were you going for a brownie?  1', '2006-01-11 00:22:58.000000', NULL, 1),
(2024029, 279503, 42013, '<td valign="top">like the DOF</td>', 'like the DOF', '2006-01-11 00:23:14.000000', NULL, 1),
(2024037, 276844, 45961, '<td valign="top">You make my mouth water already. Great composition, but I think I would have liked to see better focusing on one of the cookies. Either that or my tummy is growling like a maniac. Personally if you have used a different surface to put these cookies on, it might has been better. This is a 7 for me.</td>', 'You make my mouth water already. Great composition, but I think I would have liked to see better focusing on one of the cookies. Either that or my tummy is growling like a maniac. Personally if you have used a different surface to put these cookies on, it might has been better. This is a 7 for me.', '2006-01-11 00:24:18.000000', NULL, 1),
(2024038, 279581, 42013, '<td valign="top">very nice setup with line of plate breaking up the finish product from the ingredients giving a nice contrast.</td>', 'very nice setup with line of plate breaking up the finish product from the ingredients giving a nice contrast.', '2006-01-11 00:24:23.000000', NULL, 1),
(2024045, 278884, 10848, '<td valign="top">This looks delicious! Very impressive image.</td>', 'This looks delicious! Very impressive image.', '2006-01-11 00:25:02.000000', NULL, 1),
