(2024390, 279357, 49007, '<td valign="top">Lose the stove in as a background. I like the ingredients and pot.</td>', 'Lose the stove in as a background. I like the ingredients and pot.', '2006-01-11 01:24:01.000000', NULL, 1),
(2024392, 279357, 32079, '<td valign="top">nice angle and layout.  overall, a tad bit underexposed, colors (esp. blue) seem over saturated</td>', 'nice angle and layout.  overall, a tad bit underexposed, colors (esp. blue) seem over saturated', '2006-01-11 01:24:12.000000', NULL, 1),
