(2024406, 279553, 49007, '<td valign="top">That''s funny. I just saw a recipe book for this today. Lighting is overdone. I know the stove is a tough spot to get good light.</td>', 'That''s funny. I just saw a recipe book for this today. Lighting is overdone. I know the stove is a tough spot to get good light.', '2006-01-11 01:27:05.000000', NULL, 1),
(2024412, 278678, 49007, '<td valign="top">Lack of focus. If you''re going to puul this one off focus on the front of the plate. Crop the top 1/4 of the image.</td>', 'Lack of focus. If you''re going to puul this one off focus on the front of the plate. Crop the top 1/4 of the image.', '2006-01-11 01:29:42.000000', NULL, 1),
