(2024467, 278372, 41091, '<td valign="top">We college students would like you to come cook for us :)  Excellently composed image.  Great use of color and vibrancy to achieve a well metered, right-on dof image submission.  If photography doesn''t work out for you, just be a chef :)</td>', 'We college students would like you to come cook for us :)  Excellently composed image.  Great use of color and vibrancy to achieve a well metered, right-on dof image submission.  If photography doesn''t work out for you, just be a chef :)', '2006-01-11 01:40:18.000000', NULL, 1),
(2024471, 279528, 41091, '<td valign="top">There is a LOT of negative space in this image.  Maybe placing the chopsticks on the plate and then cropping would take care of this.  This way, all that background isn''t left to distract the viewer from the important subject material.</td>', 'There is a LOT of negative space in this image.  Maybe placing the chopsticks on the plate and then cropping would take care of this.  This way, all that background isn''t left to distract the viewer from the important subject material.', '2006-01-11 01:41:48.000000', NULL, 1),
(2024473, 278786, 49007, '<td valign="top">Original, but the colors are dull.</td>', 'Original, but the colors are dull.', '2006-01-11 01:41:52.000000', NULL, 1),
