(2026210, 279582, 50036, '<td valign="top">Very nice, but what are the yellow lines? I like the fire behind the food.</td>', 'Very nice, but what are the yellow lines? I like the fire behind the food.', '2006-01-11 11:32:10.000000', NULL, 1),
(2026244, 278870, 35545, '<td valign="top">I''m sorry.  This just looks unappetizing.  It looks as if the avocado is lying in a plate of catsup, and the avocado has a lot of blemishes.  You obviously put a lot of thought into the composition.  Keep on shooting.</td>', 'I''m sorry.  This just looks unappetizing.  It looks as if the avocado is lying in a plate of catsup, and the avocado has a lot of blemishes.  You obviously put a lot of thought into the composition.  Keep on shooting.', '2006-01-11 11:40:27.000000', NULL, 1),
