(2026733, 279037, 44490, '<td valign="top">Nice topping design and color contrast.  More DOF would help, and less-straight-down composition would be more interesting.</td>', 'Nice topping design and color contrast.  More DOF would help, and less-straight-down composition would be more interesting.', '2006-01-11 13:55:56.000000', NULL, 1),
(2026738, 277169, 41574, '<td valign="top">I don''t know, but I just don''t buy that you made that slice of pizza (please do correct me if I''m wrong). If I''m right, you get a low grade for not following the guidelines of the challenge (it is a very nice picture, though).</td>', 'I don''t know, but I just don''t buy that you made that slice of pizza (please do correct me if I''m wrong). If I''m right, you get a low grade for not following the guidelines of the challenge (it is a very nice picture, though).', '2006-01-11 13:56:19.000000', NULL, 1),
(2026739, 278789, 44490, '<td valign="top">Nice sharpness and detail.  Wish for more color saturation and not-so-strait-on composition.</td>', 'Nice sharpness and detail.  Wish for more color saturation and not-so-strait-on composition.', '2006-01-11 13:56:23.000000', NULL, 1),
