(2026743, 279219, 45857, '<td valign="top">Rather abstract image, I don''t think I''d have a clue without the title, and still not sure exactly at what I''m seeing. For me the highlights are disturbing, if that''s the pudding at the bottom, then the colors have gone over to something unpleasant</td>', 'Rather abstract image, I don''t think I''d have a clue without the title, and still not sure exactly at what I''m seeing. For me the highlights are disturbing, if that''s the pudding at the bottom, then the colors have gone over to something unpleasant', '2006-01-11 13:56:43.000000', NULL, 1),
(2026746, 278776, 41574, '<td valign="top">I love the inclusion of the whole grains. The bread looks great, too.</td>', 'I love the inclusion of the whole grains. The bread looks great, too.', '2006-01-11 13:57:01.000000', NULL, 1),
(2026749, 279443, 44490, '<td valign="top">Nice colors and composition.  More DOF and fewer elements would be better.</td>', 'Nice colors and composition.  More DOF and fewer elements would be better.', '2006-01-11 13:57:38.000000', NULL, 1),
