(2026780, 277982, 45857, '<td valign="top">Realistic approach, I like the arrangement, especially the skewed onion. You did a good job with DOF. My only suggestion would be that had you hollowed out the bun it would have snuggled down on the hamburger and looked less precarious.</td>', 'Realistic approach, I like the arrangement, especially the skewed onion. You did a good job with DOF. My only suggestion would be that had you hollowed out the bun it would have snuggled down on the hamburger and looked less precarious.', '2006-01-11 14:05:50.000000', NULL, 1),
(2026785, 277133, 12578, '<td valign="top">shame about the lines ( white card used I presume as a under plate back ground) near the bottom right of the spoon handle. Otherwise Nice and I like the grain in the image - works well</td>', 'shame about the lines ( white card used I presume as a under plate back ground) near the bottom right of the spoon handle. Otherwise Nice and I like the grain in the image - works well', '2006-01-11 14:06:57.000000', NULL, 1),
