INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2027711, 278396, 36831, '<td valign="top">Very nice. I was going to score it lower until I realized the specks on your image were actually on MY screen. Once dusted I realized that they showed up on your image because your black was a true black! Very nice picture. Perfect focus, and exposure. This will score high. Good luck.</td>', 'Very nice. I was going to score it lower until I realized the specks on your image were actually on MY screen. Once dusted I realized that they showed up on your image because your black was a true black! Very nice picture. Perfect focus, and exposure. This will score high. Good luck.', '2006-01-11 18:58:00.000000', NULL, 1),
