(2028567, 278081, 41574, '<td valign="top">Excellent.</td>', 'Excellent.', '2006-01-11 23:31:45.000000', NULL, 1),
(2028573, 279094, 41574, '<td valign="top">What...what the hell is that? I think the dead-center framing actually works here, and the leaves keep the shot from looking too plain. Seriously, though...what am I looking at?</td>', 'What...what the hell is that? I think the dead-center framing actually works here, and the leaves keep the shot from looking too plain. Seriously, though...what am I looking at?', '2006-01-11 23:32:39.000000', NULL, 1),
(2028576, 277899, 41574, '<td valign="top">The very-desaturated colors don''t really work for me, but I very much like the subject matter. Also, other than the colors, it''s a technically sound shot. You might, however, consider B&amp;W with this one.</td>', 'The very-desaturated colors don''t really work for me, but I very much like the subject matter. Also, other than the colors, it''s a technically sound shot. You might, however, consider B&W with this one.', '2006-01-11 23:33:28.000000', NULL, 1),
(2028577, 277377, 41574, '<td valign="top">Yuck: I never liked the things. Nice picture, though...very nice.</td>', 'Yuck: I never liked the things. Nice picture, though...very nice.', '2006-01-11 23:33:52.000000', NULL, 1),
(2028581, 278346, 41574, '<td valign="top">Oh, man. The background actually looks to good to be true (is it?). The presentation is ingenious, and the lighting, colors, focus, framing, etc. are all top-notch. Great work!</td>', 'Oh, man. The background actually looks to good to be true (is it?). The presentation is ingenious, and the lighting, colors, focus, framing, etc. are all top-notch. Great work!', '2006-01-11 23:35:31.000000', NULL, 1),
(2028586, 278774, 41574, '<td valign="top">Eewww. Not the daal, the photo. No offense, but why did you submit this? Assuming you were sincere in your submission, here''s a critique: there''s significant camera-shake, the choice of framing if unappealing and poor, the white balance is way off...it''s just a really bad shot. Sorry if this is harsh, but, well...come on. I can''t even give you a higher grade based on bias as a result of its being Indian. Really, try harder next time.</td>', 'Eewww. Not the daal, the photo. No offense, but why did you submit this? Assuming you were sincere in your submission, here''s a critique: there''s significant camera-shake, the choice of framing if unappealing and poor, the white balance is way off...it''s just a really bad shot. Sorry if this is harsh, but, well...come on. I can''t even give you a higher grade based on bias as a result of its being Indian. Really, try harder next time.', '2006-01-11 23:37:46.000000', NULL, 1),
(2028588, 279571, 41574, '<td valign="top">Nice shot.</td>', 'Nice shot.', '2006-01-11 23:37:59.000000', NULL, 1),
(2028591, 277968, 41574, '<td valign="top">The bird? Nah.</td>', 'The bird? Nah.', '2006-01-11 23:38:19.000000', NULL, 1),
