(2030073, 276851, 43774, '<td valign="top">Nice, looks good, DOF is too shallow, crop is too tight.</td>', 'Nice, looks good, DOF is too shallow, crop is too tight.', '2006-01-12 13:06:33.000000', NULL, 1),
(2030075, 279031, 43774, '<td valign="top">Nice presentation, is the focus just slightly off? Maybe it needs sharpening.</td>', 'Nice presentation, is the focus just slightly off? Maybe it needs sharpening.', '2006-01-12 13:07:14.000000', NULL, 1),
(2030078, 279498, 50695, '<td valign="top">boring centered placement for an otherwise excellent shot. I think just cropping off the edges would work wonders.</td>', 'boring centered placement for an otherwise excellent shot. I think just cropping off the edges would work wonders.', '2006-01-12 13:07:52.000000', NULL, 1),
(2030080, 279591, 43774, '<td valign="top">Too tight a crop, shouldn''t have cut off the edge of the plate.</td>', 'Too tight a crop, shouldn''t have cut off the edge of the plate.', '2006-01-12 13:08:05.000000', NULL, 1),
(2030081, 278091, 43774, '<td valign="top">Fuzzy, focus seems off. Colour looks good.</td>', 'Fuzzy, focus seems off. Colour looks good.', '2006-01-12 13:08:25.000000', NULL, 1),
