(2030086, 278658, 43774, '<td valign="top">Would work better with a higher angle, colours look good. Too much dead space at top.</td>', 'Would work better with a higher angle, colours look good. Too much dead space at top.', '2006-01-12 13:09:34.000000', NULL, 1),
