(2035382, 278774, 30777, '<td valign="top">Blurry, lighting and composition need work.</td>', 'Blurry, lighting and composition need work.', '2006-01-14 09:09:14.000000', NULL, 1),
(2035384, 279591, 30777, '<td valign="top">Unfortunate crop, looks yummy but a different lighting setup may have helped make it "pop"</td>', 'Unfortunate crop, looks yummy but a different lighting setup may have helped make it "pop"', '2006-01-14 09:09:52.000000', NULL, 1),
(2035385, 278658, 30777, '<td valign="top">Very nice!</td>', 'Very nice!', '2006-01-14 09:10:06.000000', NULL, 1),
(2035426, 278360, 2829, '<td valign="top">That looks like some real tasty cheesecake. I feel the background is a bit distracting though. That big white blob with 6 dark spots draws more attention than the cheesecake. I like the depth of field, but the background should have ingredients or pots and pans used to make the cheesecake.</td>', 'That looks like some real tasty cheesecake. I feel the background is a bit distracting though. That big white blob with 6 dark spots draws more attention than the cheesecake. I like the depth of field, but the background should have ingredients or pots and pans used to make the cheesecake.', '2006-01-14 09:35:28.000000', NULL, 1),
(2035428, 279581, 2829, '<td valign="top">Very nice. Love the dish and the accent of onions. Don''t like the tray''s corner in the top left corner being like that.</td>', 'Very nice. Love the dish and the accent of onions. Don''t like the tray''s corner in the top left corner being like that.', '2006-01-14 09:36:43.000000', NULL, 1),
(2035430, 279470, 2829, '<td valign="top">Someone must be a chef :)</td>', 'Someone must be a chef :)', '2006-01-14 09:37:42.000000', NULL, 1);
