(2035530, 278280, 48487, '<td valign="top">Looks deliscious.  Beautiful composition.  I wish the lighting had been directed from the camera position, to avoid the shadows.  8</td>', 'Looks deliscious.  Beautiful composition.  I wish the lighting had been directed from the camera position, to avoid the shadows.  8', '2006-01-14 10:26:14.000000', NULL, 1),
