(2035551, 278396, 42046, '<td valign="top">I love the action of the drops coming out of the glass! It must be difficult to record it.</td>', 'I love the action of the drops coming out of the glass! It must be difficult to record it.', '2006-01-14 10:38:45.000000', NULL, 1),
(2035557, 278698, 48487, '<td valign="top">Looks like a great dish, beautifully represented.  I look forward to learning to see in my mind''s eye how to arrange objects and take photographs like this.  Hope you get a ribbon.  10</td>', 'Looks like a great dish, beautifully represented.  I look forward to learning to see in my mind''s eye how to arrange objects and take photographs like this.  Hope you get a ribbon.  10', '2006-01-14 10:47:52.000000', NULL, 1),
