(2037371, 279141, 45745, '<td valign="top">this is the best hot chocolate!!</td>', 'this is the best hot chocolate!!', '2006-01-15 01:08:15.000000', NULL, 1),
(2037374, 279357, 50641, '<td valign="top">I love that you put the ingredients in the shot.  Beautiful dim sum!</td>', 'I love that you put the ingredients in the shot.  Beautiful dim sum!', '2006-01-15 01:09:17.000000', NULL, 1),
(2037474, 278051, 42984, '<td valign="top">Love the use of neutral black space to highlight the image</td>', 'Love the use of neutral black space to highlight the image', '2006-01-15 01:58:14.000000', NULL, 1),
(2037504, 277982, 45961, '<td valign="top">The fries are a bit too burnt for me, but I think it''s a great set up, quite appealing even if I''m not a big fan of burgers. It gives a very home-made feeling to it, but maybe a bit too sloppy? The arrangement inside the burger could have been a be better (neater). The cucumber I can''t figure out if it works for the picture or not. In one way it does, and then looking at it again it doesn''t. I must say your lighting is very well done though. Doesn''t have those hot spots that ruin the picture. I gave this a 7, since I thought the setup could have been immproved by a bit. Perhaps even a bit more colour to help on the contrast would have worked well as well.</td>', 'The fries are a bit too burnt for me, but I think it''s a great set up, quite appealing even if I''m not a big fan of burgers. It gives a very home-made feeling to it, but maybe a bit too sloppy? The arrangement inside the burger could have been a be better (neater). The cucumber I can''t figure out if it works for the picture or not. In one way it does, and then looking at it again it doesn''t. I must say your lighting is very well done though. Doesn''t have those hot spots that ruin the picture. I gave this a 7, since I thought the setup could have been immproved by a bit. Perhaps even a bit more colour to help on the contrast would have worked well as well.', '2006-01-15 02:36:31.000000', NULL, 1),
(2037512, 277623, 42984, '<td valign="top">Spectacular treatmetn of the ingredients.  Composition and light is great as is the control of the flare off the board</td>', 'Spectacular treatmetn of the ingredients.  Composition and light is great as is the control of the flare off the board', '2006-01-15 02:48:44.000000', NULL, 1),
