(2037930, 279141, 42638, '<td valign="top">Wow, Wonderful picture, Very sharp and focused. The colors are great! Now I need to go to the store to get some. The only improvement I can see is to straighten the horizon just a tad. Nicely done.</td>', 'Wow, Wonderful picture, Very sharp and focused. The colors are great! Now I need to go to the store to get some. The only improvement I can see is to straighten the horizon just a tad. Nicely done.', '2006-01-15 10:35:03.000000', NULL, 1),
(2037933, 277081, 42638, '<td valign="top">Wow, very nice, looks like something in a magazine! Love the colors here.</td>', 'Wow, very nice, looks like something in a magazine! Love the colors here.', '2006-01-15 10:35:57.000000', NULL, 1),
(2037935, 277081, 46468, '<td valign="top">I really love the colors and the clarity of this photo. It looks like an ad in a magazine and is making me very hungry. Fantastic focus, complimentary background color, slightly off-centered (which works very well), chopsticks off to the lefthand thirds, overall great photograph- you just received my very first 10- Good Luck</td>', 'I really love the colors and the clarity of this photo. It looks like an ad in a magazine and is making me very hungry. Fantastic focus, complimentary background color, slightly off-centered (which works very well), chopsticks off to the lefthand thirds, overall great photograph- you just received my very first 10- Good Luck', '2006-01-15 10:37:49.000000', NULL, 1),
(2037938, 279062, 46468, '<td valign="top">Very well done, fantastic focus, the steam just makes my mouth water, fantastic-9</td>', 'Very well done, fantastic focus, the steam just makes my mouth water, fantastic-9', '2006-01-15 10:38:10.000000', NULL, 1),
(2037939, 277982, 46468, '<td valign="top">Like the color and the focus, very nicely done. In fact, I am bumping this up one more-Good luck</td>', 'Like the color and the focus, very nicely done. In fact, I am bumping this up one more-Good luck', '2006-01-15 10:38:23.000000', NULL, 1),
(2037940, 279031, 46468, '<td valign="top">Well done, nicely arranged, the white plate really shows off the chocolate coating and emphasizes the white drizzle. Only thing I would have liked to see differently is for the strawberries to be more red at the tops and the greenery to be more perky. Overall and really great pic-Good luck</td>', 'Well done, nicely arranged, the white plate really shows off the chocolate coating and emphasizes the white drizzle. Only thing I would have liked to see differently is for the strawberries to be more red at the tops and the greenery to be more perky. Overall and really great pic-Good luck', '2006-01-15 10:38:41.000000', NULL, 1),
(2037941, 279470, 46468, '<td valign="top">Pleasing colors, nice focus, I like the little touches you have added to the photo; the chocolate heart, the hand reaching for the cherry, the angle- Good luck, nicely done</td>', 'Pleasing colors, nice focus, I like the little touches you have added to the photo; the chocolate heart, the hand reaching for the cherry, the angle- Good luck, nicely done', '2006-01-15 10:38:52.000000', NULL, 1),
(2037945, 278824, 46468, '<td valign="top">Between the great focus, brillant colors, and stop action to the water, this one really "pops". Nicely done-8</td>', 'Between the great focus, brillant colors, and stop action to the water, this one really "pops". Nicely done-8', '2006-01-15 10:39:43.000000', NULL, 1),
(2037947, 279321, 46468, '<td valign="top">Fantastic colors, great focus, and original thought. Very well done. Only thing that is a very MINOR distraction is the slight glare on the noodle package by the R in Ramen -8</td>', 'Fantastic colors, great focus, and original thought. Very well done. Only thing that is a very MINOR distraction is the slight glare on the noodle package by the R in Ramen -8', '2006-01-15 10:40:10.000000', NULL, 1),
(2037949, 277623, 46468, '<td valign="top">Really love the arrangement, well thought out. I like how you included the seasoning and tools too. Great focus and very colorful. I don''t usually like borders but it works well with this picture. Good luck</td>', 'Really love the arrangement, well thought out. I like how you included the seasoning and tools too. Great focus and very colorful. I don''t usually like borders but it works well with this picture. Good luck', '2006-01-15 10:40:54.000000', NULL, 1),
(2037950, 279357, 46468, '<td valign="top">I really like the angle, the way the food is arranged on the plate, the focus, and the fact that you not only showed the finished product, but have the ingredients in the background also. Bumping this up one more</td>', 'I really like the angle, the way the food is arranged on the plate, the focus, and the fact that you not only showed the finished product, but have the ingredients in the background also. Bumping this up one more', '2006-01-15 10:41:05.000000', NULL, 1),
(2037955, 279039, 42638, '<td valign="top">Nicely done, I could see this in a cookbook. Love the colors, details and lighting. Great composition.</td>', 'Nicely done, I could see this in a cookbook. Love the colors, details and lighting. Great composition.', '2006-01-15 10:44:29.000000', NULL, 1),
(2037977, 276987, 42638, '<td valign="top">Nicely done. Love the colors here, the black spoons really emphasize the reds.</td>', 'Nicely done. Love the colors here, the black spoons really emphasize the reds.', '2006-01-15 11:03:30.000000', NULL, 1),
(2037981, 279281, 42638, '<td valign="top">Nice picture, Great capture. Love the splash and the focus is dead on. Not the typical way to make scrambled eggs...good idea.</td>', 'Nice picture, Great capture. Love the splash and the focus is dead on. Not the typical way to make scrambled eggs...good idea.', '2006-01-15 11:04:42.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2037986, 279396, 42638, '<td valign="top">Very nice, I love the ghostly flames with the steak in focus. The only thing I can suggest is to move the steak off the middle maybe toward the bottom of the frame.</td>', 'Very nice, I love the ghostly flames with the steak in focus. The only thing I can suggest is to move the steak off the middle maybe toward the bottom of the frame.', '2006-01-15 11:05:51.000000', NULL, 1),
(2037990, 278824, 42638, '<td valign="top">Nicely done. Love the rich green and red here. The water droplets are nicely focused. Good job!</td>', 'Nicely done. Love the rich green and red here. The water droplets are nicely focused. Good job!', '2006-01-15 11:06:45.000000', NULL, 1),
(2037991, 278346, 42638, '<td valign="top">Very creative and well executed, Took me a minute to see the foot but thats just me. Nicely done!</td>', 'Very creative and well executed, Took me a minute to see the foot but thats just me. Nicely done!', '2006-01-15 11:07:36.000000', NULL, 1),
(2037993, 277208, 24940, '<td valign="top">Watch that date stamp - no text allowed - see rules...<br/> <br/>Must be new math - that "pork chop" looks an awful lot like an onion!  :))<br/> <br/>Seriously - the overall focus is pretty bad.  Is that a contact lens to the right of the pork chop, er, onion?</td>', 'Watch that date stamp - no text allowed - see rules... Must be new math - that "pork chop" looks an awful lot like an onion!  :)) Seriously - the overall focus is pretty bad.  Is that a contact lens to the right of the pork chop, er, onion?', '2006-01-15 11:08:51.000000', NULL, 1),
(2037995, 277377, 42638, '<td valign="top">Wow, love this one, Nice focus and coloring. Besides being a great picture, it really brings out some fond memories for me, Thank you. Its always nice when emotions are affected.</td>', 'Wow, love this one, Nice focus and coloring. Besides being a great picture, it really brings out some fond memories for me, Thank you. Its always nice when emotions are affected.', '2006-01-15 11:09:35.000000', NULL, 1),
(2037999, 279398, 42638, '<td valign="top">Good picture, love the colors here, the background really accentuates the plate, Nice touch with the peppers at the top. Nicely done.</td>', 'Good picture, love the colors here, the background really accentuates the plate, Nice touch with the peppers at the top. Nicely done.', '2006-01-15 11:10:51.000000', NULL, 1),
(2038002, 279519, 42638, '<td valign="top">Vert nice, Love the colors here. The spot on the left chunk of meat is a bit washed but good composition.</td>', 'Vert nice, Love the colors here. The spot on the left chunk of meat is a bit washed but good composition.', '2006-01-15 11:11:48.000000', NULL, 1),
