(2042942, 279087, 12578, '<td valign="top">First thought that the bowl was reflecting something but must be a pattern, You should have turned this the other way as this is very distracting being the darkest point of the image which also sits on two rules of thirds lines, the food looks amazingly fresh as the filo poastry is still nice and moist :0) Good use of DOF but the top right also distracts me a little too. Might have left a little room between the rice bowl and the dim sum plate too, great shot gonna give you an 8</td>', 'First thought that the bowl was reflecting something but must be a pattern, You should have turned this the other way as this is very distracting being the darkest point of the image which also sits on two rules of thirds lines, the food looks amazingly fresh as the filo poastry is still nice and moist :0) Good use of DOF but the top right also distracts me a little too. Might have left a little room between the rice bowl and the dim sum plate too, great shot gonna give you an 8', '2006-01-16 13:19:16.000000', NULL, 1),
(2042944, 279414, 12578, '<td valign="top">Lovely colours cant wait to see the recipe on this one but the only distracting thing for me in this shot id the one large spinach leaf at the front with all the highlights on it as its seems to drop my focal plain right down taking my eyes off those sumptuous meat balls. 8</td>', 'Lovely colours cant wait to see the recipe on this one but the only distracting thing for me in this shot id the one large spinach leaf at the front with all the highlights on it as its seems to drop my focal plain right down taking my eyes off those sumptuous meat balls. 8', '2006-01-16 13:20:56.000000', NULL, 1),
(2042950, 278249, 12578, '<td valign="top">Looks fantastic but I think I would like to see a couple of the prawns as I am looking harder to see whats in it, could also have benefited from having a couple of muscles on the top. That aside I love the composistion , lighting is great and the colours are all great on my monitor. 9</td>', 'Looks fantastic but I think I would like to see a couple of the prawns as I am looking harder to see whats in it, could also have benefited from having a couple of muscles on the top. That aside I love the composistion , lighting is great and the colours are all great on my monitor. 9', '2006-01-16 13:23:06.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2042958, 279498, 12578, '<td valign="top">Minimal layout yet works so well, nice contrast in the reds and greens and the lighting is spot on, gonna have to 9 this one.</td>', 'Minimal layout yet works so well, nice contrast in the reds and greens and the lighting is spot on, gonna have to 9 this one.', '2006-01-16 13:24:39.000000', NULL, 1),
(2042968, 278698, 12578, '<td valign="top">great composition but I think that I would really like to see at least one edge of the plate - can''t explain it but it just lacks that little something which I think that is what it is, good lighting and good contrasting reds on greens, only thing I might have done different is drizzle the tomatoes around the front of the nut roast. Great shot good luck</td>', 'great composition but I think that I would really like to see at least one edge of the plate - can''t explain it but it just lacks that little something which I think that is what it is, good lighting and good contrasting reds on greens, only thing I might have done different is drizzle the tomatoes around the front of the nut roast. Great shot good luck', '2006-01-16 13:26:55.000000', NULL, 1),
(2042997, 279324, 12578, '<td valign="top">great angles, i''d lose the border to be honest and Im not sure about whole prawns in there shells as apetizing? Tails on yeah but.... I dunno its a great shot which just doesn''t make me feel like I''d make it if I saw it in a recipe book. 7 none the less. (Forgot to say I think the prawns are a fantasticly natural colour :0) )</td>', 'great angles, i''d lose the border to be honest and Im not sure about whole prawns in there shells as apetizing? Tails on yeah but.... I dunno its a great shot which just doesn''t make me feel like I''d make it if I saw it in a recipe book. 7 none the less. (Forgot to say I think the prawns are a fantasticly natural colour :0) )', '2006-01-16 13:29:47.000000', NULL, 1),
