(2050294, 279582, 2829, '<td valign="top">Very nice set up, but the streak above the flame is distracting</td>', 'Very nice set up, but the streak above the flame is distracting', '2006-01-17 20:23:23.000000', NULL, 1),
(2050297, 278346, 44172, '<td valign="top">wow - very, VERY clever and a high quality image with great focus and lighting (love your plate pattern) - nice work :)</td>', 'wow - very, VERY clever and a high quality image with great focus and lighting (love your plate pattern) - nice work :)', '2006-01-17 20:23:34.000000', NULL, 1),
(2050304, 279320, 50427, '<td valign="top">I find the spaghetti in the background distracting. Some sharper reflection in the knife I think would help define it for what it is.</td>', 'I find the spaghetti in the background distracting. Some sharper reflection in the knife I think would help define it for what it is.', '2006-01-17 20:26:00.000000', NULL, 1),
(2050305, 278698, 44172, '<td valign="top">WOW - another image that could be in a magazine, lighting seems a bit too much - not sure on that though - wonderful macro and the colors are great with good balance - would love to try this - looks great - nice work :)</td>', 'WOW - another image that could be in a magazine, lighting seems a bit too much - not sure on that though - wonderful macro and the colors are great with good balance - would love to try this - looks great - nice work :)', '2006-01-17 20:26:11.000000', NULL, 1),
(2050309, 279016, 50427, '<td valign="top">Very interesting take on the challenge, however I doubt that this meets the "Prepare 1 or more dishes from a recipe" part of the challenge.</td>', 'Very interesting take on the challenge, however I doubt that this meets the "Prepare 1 or more dishes from a recipe" part of the challenge.', '2006-01-17 20:27:28.000000', NULL, 1),
(2050319, 278870, 50427, '<td valign="top">Very interesting, curious about the cuisine that includes this dish. I think the composition could have been improved by viewing this setting from an angle, leaving a bit more space around the edge of the plate, and by keeping all of the wine glass in the frame.</td>', 'Very interesting, curious about the cuisine that includes this dish. I think the composition could have been improved by viewing this setting from an angle, leaving a bit more space around the edge of the plate, and by keeping all of the wine glass in the frame.', '2006-01-17 20:29:55.000000', NULL, 1),
(2050326, 278280, 47020, '<td valign="top">Looks yummy.  :-)<br/> <br/>A few critical suggestions on the image: (1) I find the cropping to be distracting -- I''d like to see all of the rice, and all of the dish...  Having the chopsticks go off the edge _might_ be OK, and having the mat go off _is_ OK... I just wish to see all of the actual food, in this image.  (2) it might also be nice if the depth of field were slightly deeper.  Finally, (3) it seems that the colors look more muted than I imagine they would actually be -- it would be nice if they would really pop, particularly the reds of the peppers and the orange of the (beautifully done) carrot-flower.<br/> <br/>Still, it looks tasty.  I hope you enjoyed eating it.  :-)</td>', 'Looks yummy.  :-) A few critical suggestions on the image: (1) I find the cropping to be distracting -- I''d like to see all of the rice, and all of the dish...  Having the chopsticks go off the edge _might_ be OK, and having the mat go off _is_ OK... I just wish to see all of the actual food, in this image.  (2) it might also be nice if the depth of field were slightly deeper.  Finally, (3) it seems that the colors look more muted than I imagine they would actually be -- it would be nice if they would really pop, particularly the reds of the peppers and the orange of the (beautifully done) carrot-flower. Still, it looks tasty.  I hope you enjoyed eating it.  :-)', '2006-01-17 20:31:46.000000', NULL, 1),
(2050327, 279324, 47020, '<td valign="top">FYI, I find the border stripe on this image to be very distracting.  I''ve seen the same technique work well on other images, so it can certainly work... I just find it distracting, here.  Perhaps if the image was cropped differently, it would work better?</td>', 'FYI, I find the border stripe on this image to be very distracting.  I''ve seen the same technique work well on other images, so it can certainly work... I just find it distracting, here.  Perhaps if the image was cropped differently, it would work better?', '2006-01-17 20:33:52.000000', NULL, 1),
(2050328, 279202, 50427, '<td valign="top">Looks very interesting. I''d like to see a bit more definition in the mushrooms, onions, and ?orange?; a wider depth of field would help, I think.</td>', 'Looks very interesting. I''d like to see a bit more definition in the mushrooms, onions, and ?orange?; a wider depth of field would help, I think.', '2006-01-17 20:34:15.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2050332, 279281, 50427, '<td valign="top">Great action shot. How did you get the egg to stand up like that?  Did you actually "Prepare 1 or more dishes from a recipe" for this shot?</td>', 'Great action shot. How did you get the egg to stand up like that?  Did you actually "Prepare 1 or more dishes from a recipe" for this shot?', '2006-01-17 20:35:18.000000', NULL, 1),
(2050336, 279531, 50427, '<td valign="top">Beautiful composition. Personally, I''d like a wider depth of field to see more detail in the pear.</td>', 'Beautiful composition. Personally, I''d like a wider depth of field to see more detail in the pear.', '2006-01-17 20:36:39.000000', NULL, 1),
(2050338, 279037, 47020, '<td valign="top">I think this might be one of those rare images where centering works well...  Anyway, I find that I (if only me) am distracted by the crop on the right.</td>', 'I think this might be one of those rare images where centering works well...  Anyway, I find that I (if only me) am distracted by the crop on the right.', '2006-01-17 20:37:40.000000', NULL, 1),
(2050339, 279585, 50427, '<td valign="top">Love the red/fuschia straws to offset the green drink. Unfortunately, I feel like the classes are leaning to the right a bit. Not sure if it''s the crop or an optical illusion.</td>', 'Love the red/fuschia straws to offset the green drink. Unfortunately, I feel like the classes are leaning to the right a bit. Not sure if it''s the crop or an optical illusion.', '2006-01-17 20:37:57.000000', NULL, 1),
(2050343, 277623, 47020, '<td valign="top">I really like this interpretation of this challenge.  (And the image is nice, too.  ;-)</td>', 'I really like this interpretation of this challenge.  (And the image is nice, too.  ;-)', '2006-01-17 20:38:47.000000', NULL, 1),
(2050347, 279087, 44172, '<td valign="top">would be a bit better to me if the bowl didn''t have that dark spot on it - a great image though - very classy - and it looks tasty! nice work :)</td>', 'would be a bit better to me if the bowl didn''t have that dark spot on it - a great image though - very classy - and it looks tasty! nice work :)', '2006-01-17 20:40:50.000000', NULL, 1),
(2050356, 277899, 44172, '<td valign="top">original idea - I always wanted to try making homeade pasta - that''s interesting the name on the machine - "al dente" - good job :)</td>', 'original idea - I always wanted to try making homeade pasta - that''s interesting the name on the machine - "al dente" - good job :)', '2006-01-17 20:41:48.000000', NULL, 1),
(2050367, 279459, 44172, '<td valign="top">the lighting seems a bit harsh and the focus could be a little better, but the whole oreos as well as the broken up ones in the dish off to the side is a very nice touch - looks really yummy - can''t wait to get the recipe off your comments  - nice work :)</td>', 'the lighting seems a bit harsh and the focus could be a little better, but the whole oreos as well as the broken up ones in the dish off to the side is a very nice touch - looks really yummy - can''t wait to get the recipe off your comments  - nice work :)', '2006-01-17 20:43:43.000000', NULL, 1),
(2050375, 279541, 44172, '<td valign="top">the red and white cloth is a nice touch, the beer looks a little strange - would have been better if it were very clear and not cropped off on the top - a very nice image though - looks like something out of "Country Cooking" or something - good job :)</td>', 'the red and white cloth is a nice touch, the beer looks a little strange - would have been better if it were very clear and not cropped off on the top - a very nice image though - looks like something out of "Country Cooking" or something - good job :)', '2006-01-17 20:45:49.000000', NULL, 1),
(2050386, 278869, 44172, '<td valign="top">could be a bit larger and the focus could be a lot better but the composition, layout and frame are all very nice :)</td>', 'could be a bit larger and the focus could be a lot better but the composition, layout and frame are all very nice :)', '2006-01-17 20:48:00.000000', NULL, 1),
(2050388, 279420, 44172, '<td valign="top">that string is a bit distracting but the lighting, DOF and colors are all very good - looks tasty! nice job :)</td>', 'that string is a bit distracting but the lighting, DOF and colors are all very good - looks tasty! nice job :)', '2006-01-17 20:49:13.000000', NULL, 1),
(2050399, 277528, 44172, '<td valign="top">I think I''d like this better if the empty pan with the stained bottom and the little glass dish of butter were not in it. I like the colors very much and the soft focus is a very nice touch - good job :)</td>', 'I think I''d like this better if the empty pan with the stained bottom and the little glass dish of butter were not in it. I like the colors very much and the soft focus is a very nice touch - good job :)', '2006-01-17 20:51:05.000000', NULL, 1),
(2050405, 277675, 44172, '<td valign="top">kind of small, focus could be a bit better and not very interesting compared to the other entries - but I do like the use of off centering "THE egg" :)</td>', 'kind of small, focus could be a bit better and not very interesting compared to the other entries - but I do like the use of off centering "THE egg" :)', '2006-01-17 20:52:57.000000', NULL, 1),
(2050446, 279359, 2829, '<td valign="top">Very nice lighting</td>', 'Very nice lighting', '2006-01-17 21:04:08.000000', NULL, 1),
(2050481, 279582, 44172, '<td valign="top">wow - great shot - looks like an outdoor barbecue - wish I lived where you are - it''s 9 degrees outside right now - and I could go for a nice fresh grilled burger from outside! The very fresh ground beef coming out of the grinder weirds me out a little bit when everything else seems so prepared and ready - love the colors though - and the flames in the background are an excellent touch - nice work and good luck :)</td>', 'wow - great shot - looks like an outdoor barbecue - wish I lived where you are - it''s 9 degrees outside right now - and I could go for a nice fresh grilled burger from outside! The very fresh ground beef coming out of the grinder weirds me out a little bit when everything else seems so prepared and ready - love the colors though - and the flames in the background are an excellent touch - nice work and good luck :)', '2006-01-17 21:13:52.000000', NULL, 1),
(2050488, 278764, 2829, '<td valign="top">Photo appears to be blurry, the corners do not have a consistent background. Yummy looking cheesecake though.</td>', 'Photo appears to be blurry, the corners do not have a consistent background. Yummy looking cheesecake though.', '2006-01-17 21:15:19.000000', NULL, 1),
(2050501, 279206, 39429, '<td valign="top">It look a while to see the bg was the "she".</td>', 'It look a while to see the bg was the "she".', '2006-01-17 21:17:44.000000', NULL, 1),
(2050529, 279062, 39429, '<td valign="top">Love the steam and texture. Bumped to 10- top pick.</td>', 'Love the steam and texture. Bumped to 10- top pick.', '2006-01-17 21:24:23.000000', NULL, 1),
(2050532, 278081, 39429, '<td valign="top">Wonderful technicals and aesthetics - 9<br/></td>', 'Wonderful technicals and aesthetics - 9', '2006-01-17 21:25:10.000000', NULL, 1),
(2050534, 277812, 44490, '<td valign="top">Best composition for the challenge in my opinion, an actual recipe!  Nice elements, especially the flame, colors, arrangement, texture, DOF, and composition.  Less background pattern, more saturation, and more sharpness would help.  Tasty, and I hope that it takes a ribbon.</td>', 'Best composition for the challenge in my opinion, an actual recipe!  Nice elements, especially the flame, colors, arrangement, texture, DOF, and composition.  Less background pattern, more saturation, and more sharpness would help.  Tasty, and I hope that it takes a ribbon.', '2006-01-17 21:25:23.000000', NULL, 1),
(2050536, 279531, 39429, '<td valign="top">Fabulous in it''s simplicity and composition.  You even avoided the discoloring that comes with cut pears.  9</td>', 'Fabulous in it''s simplicity and composition.  You even avoided the discoloring that comes with cut pears.  9', '2006-01-17 21:26:21.000000', NULL, 1),
(2050542, 276987, 39429, '<td valign="top">Beautiful presentation, nice lighting - but the extra details are what make this special - 9</td>', 'Beautiful presentation, nice lighting - but the extra details are what make this special - 9', '2006-01-17 21:27:12.000000', NULL, 1),
(2050543, 278698, 44490, '<td valign="top">Beautiful colors and compostion, good sharpness, DOF, and clean background with faded out plate.  Love it.</td>', 'Beautiful colors and compostion, good sharpness, DOF, and clean background with faded out plate.  Love it.', '2006-01-17 21:27:21.000000', NULL, 1),
(2050545, 279582, 39429, '<td valign="top">The presentation works well for you.  You''ve managed the details to make them really strong.  The grinder is a wonderful touch. 8</td>', 'The presentation works well for you.  You''ve managed the details to make them really strong.  The grinder is a wonderful touch. 8', '2006-01-17 21:28:31.000000', NULL, 1),
(2050548, 277377, 39429, '<td valign="top">Very simple, yet very effective. 8</td>', 'Very simple, yet very effective. 8', '2006-01-17 21:29:03.000000', NULL, 1),
(2050554, 278698, 39429, '<td valign="top">Beautiful and well presented.  It''s a unique recipe that shines. 8</td>', 'Beautiful and well presented.  It''s a unique recipe that shines. 8', '2006-01-17 21:29:42.000000', NULL, 1),
(2050555, 279581, 44490, '<td valign="top">Nice textures and shapes, sharpness, and pretty good composition and DOF - wish for just a touch more DOF.  Angled tray would be better to reduce the rectilinear line on the left.  Very nice image, hope it does well.</td>', 'Nice textures and shapes, sharpness, and pretty good composition and DOF - wish for just a touch more DOF.  Angled tray would be better to reduce the rectilinear line on the left.  Very nice image, hope it does well.', '2006-01-17 21:29:43.000000', NULL, 1),
(2050565, 277081, 44490, '<td valign="top">Nice elements, colors and shapes, good composition, focus, sharpness, and DOF.  Maybe a touch more saturation would help.</td>', 'Nice elements, colors and shapes, good composition, focus, sharpness, and DOF.  Maybe a touch more saturation would help.', '2006-01-17 21:31:34.000000', NULL, 1),
(2050568, 279519, 44490, '<td valign="top">Nice arrangement, colors, sharpness, and composition.  A touch more saturation might help.  Looks tasty, and hope it does well.</td>', 'Nice arrangement, colors, sharpness, and composition.  A touch more saturation might help.  Looks tasty, and hope it does well.', '2006-01-17 21:33:06.000000', NULL, 1),
(2050571, 279470, 44490, '<td valign="top">Decorative and colorful, and I especially like the hand placing the cherry as a finishing touch in more ways than one.  Very nice image.</td>', 'Decorative and colorful, and I especially like the hand placing the cherry as a finishing touch in more ways than one.  Very nice image.', '2006-01-17 21:34:16.000000', NULL, 1),
